type User { name: String!  posts: [Post!]! }
type Post { title: String! }

el title del post 2 falla:
  title  es String!   -> el post 2 no puede ser null
  [Post!]!            -> la lista no admite un ítem null, así que no puede ser null
  User.posts es !     -> posts no puede ser null
  user(id) es anulable-> user pasa a ser null

resultado:  { "data": { "user": null }, "errors": [ ... ] }

message Book {
	string title = 1;
	int32 year = 2;
}
service Library {
	rpc Get (BookId) returns (Book);                 // unary
	rpc Upload (stream Chunk) returns (Summary);     // client streaming
}
